"use strict";

var _utilities = require("../../../utilities");
var _LocationsFilter = require("../LocationsFilter.utils");
describe('LocationFilter.utils', function () {
  describe('convertListTemplatesToFilterOptions', function () {
    it('return empty', function () {
      expect((0, _LocationsFilter.convertLocationsToFilterOptions)(null)).toEqual([]);
    });
    it('should generate a function', function () {
      var locations = [{
        id: '123',
        name: 'test'
      }];
      var options = [{
        id: '123',
        label: 'test'
      }];
      expect((0, _LocationsFilter.convertLocationsToFilterOptions)(locations)).toEqual(options);
    });
  });
});
describe('getLocationOptions', function () {
  var locations = [{
    id: '10',
    name: 'Downing Street'
  }, {
    id: '742',
    name: 'Evergreen Terrace'
  }, {
    id: '1313',
    name: 'Mockingbird Lane'
  }, {
    id: '1600',
    name: 'Pennsylvania Avenue'
  }];
  var locationGroups = [{
    id: 'abc',
    name: 'Fictional Addresses'
  }, {
    id: 'def',
    name: 'Real Addresses'
  }];
  it('renders without headers when there are no location groups', function () {
    var locationOptions = (0, _LocationsFilter.getLocationOptions)([], locations);
    expect(locationOptions).toEqual(locations);
  });
  it('renders without headers when location groups is undefined', function () {
    var locationOptions = (0, _LocationsFilter.getLocationOptions)(undefined, locations);
    expect(locationOptions).toEqual(locations);
  });
  it('renders with headers when location groups are specified', function () {
    var locationOptions = (0, _LocationsFilter.getLocationOptions)(locationGroups, locations);
    expect(locationOptions).toEqual([{
      id: 'locationGroups',
      name: 'Organizations',
      optionType: _LocationsFilter.OPTION_TYPES.HEADER
    }].concat(locationGroups, [{
      id: 'locations',
      name: 'Locations',
      optionType: _LocationsFilter.OPTION_TYPES.HEADER
    }], locations));
  });
});
describe('handleOnAdd', function () {
  it('should prepend locationId if the value is not a location group ID', function () {
    var callback = jest.fn();
    var value = {
      filterName: _utilities.FILTER_NAMES.locationIds,
      id: 'test',
      name: 'Testing with non-ID'
    };
    (0, _LocationsFilter.handleOnAdd)(callback)(value);
    expect(callback.mock.calls[0][0]).toEqual(_utilities.FILTER_NAMES.locationIds);
    expect(callback.mock.calls[0][3]).toEqual(value);
  });
  it('should prepend locationGroupId if the value is a location group ID', function () {
    var callback = jest.fn();
    var id = btoa('LocationGroup:abcde');
    var value = {
      filterName: _utilities.FILTER_NAMES.locationGroupIds,
      id: id,
      name: 'Testing with location group'
    };
    (0, _LocationsFilter.handleOnAdd)(callback)(value);
    expect(callback.mock.calls[0][0]).toEqual(_utilities.FILTER_NAMES.locationGroupIds);
    expect(callback.mock.calls[0][3]).toEqual(value);
  });
  it('should handle automatic closing if only one location is allowed to be selected', function () {
    var callback = jest.fn();
    var logger = jest.fn();
    var onClose = jest.fn();
    (0, _LocationsFilter.handleOnAdd)(callback, logger, onClose, true)({
      id: 'test',
      name: 'Location'
    });
    expect(onClose).toHaveBeenCalled();
  });
});
describe('handleOnClear', function () {
  it('should clear both locationIds and locationGroupIds', function () {
    var callback = jest.fn();
    var setter = jest.fn();
    (0, _LocationsFilter.handleOnClear)(callback, undefined, setter)('test');
    expect(callback.mock.calls[0][0]).toEqual('');
    expect(callback.mock.calls[0][1]).toEqual(setter);
    expect(callback.mock.calls[0][3]).toEqual('test');
  });
});
describe('handleOnRemove', function () {
  it('should prepend locationId if the value is not a location group ID', function () {
    var callback = jest.fn();
    (0, _LocationsFilter.handleOnRemove)(callback)('test');
    expect(callback.mock.calls[0][0]).toEqual(_utilities.FILTER_NAMES.locationIds);
    expect(callback.mock.calls[0][3]).toEqual('test');
  });
  it('should prepend locationGroupId if the value is a location group ID', function () {
    var callback = jest.fn();
    var id = btoa('LocationGroup:abcde');
    (0, _LocationsFilter.handleOnRemove)(callback)(id);
    expect(callback.mock.calls[0][0]).toEqual(_utilities.FILTER_NAMES.locationGroupIds);
    expect(callback.mock.calls[0][3]).toEqual(id);
  });
});
describe('setInitialSelectedLocation', function () {
  var addOptionToFilter = jest.fn();
  var setCanInitializeDefaultLocation = jest.fn();
  it('call functions', function () {
    (0, _LocationsFilter.setInitialSelectedLocation)({
      addOptionToFilter: addOptionToFilter,
      canInitializeDefaultLocation: true,
      currentLocation: {
        location: {
          id: '1',
          name: 'Location 1'
        }
      },
      selectedSize: 0,
      setCanInitializeDefaultLocation: setCanInitializeDefaultLocation
    });
    expect(addOptionToFilter).toBeCalled();
    expect(setCanInitializeDefaultLocation).toBeCalled();
  });
  it('should not call functions', function () {
    (0, _LocationsFilter.setInitialSelectedLocation)({
      addOptionToFilter: addOptionToFilter,
      canInitializeDefaultLocation: false,
      currentLocation: {
        location: {
          id: '1',
          name: 'Location 1'
        }
      },
      selectedSize: 0,
      setCanInitializeDefaultLocation: setCanInitializeDefaultLocation
    });
    expect(addOptionToFilter).not.toBeCalled();
    expect(setCanInitializeDefaultLocation).not.toBeCalled();
  });
});